    use crate::os_store::test_support::assert_wire_witness as assert_witness;
    assert_witness::<DemoMutation>(include_str!("../../🧫️fixtures/🧬️mutations/🧮️demo/🧬️mutations/🔢️set-n/🧫️fixtures/🧾️wire-witness/🦠️mutation/🔣️.json"));
