fn assert_round_trip(text: &str, spec: &RecordSpec) {
    let opts = ParseOptions::default();
    let value = parse(text, spec, &opts).unwrap_or_else(|e| panic!("parse failed for {text:?}: {e}"));
    let printed = print(&value, spec, JoinMode::Document);
