    let inline_opts = ParseOptions { limits: Limits::default(), mode: SourceMode::Inline };
    let reparsed = parse(&inline_text, spec, &inline_opts).unwrap_or_else(|e| panic!("inline reparse failed: {e}\ninline:\n{inline_text}"));
